DECLARE client uuid:=gen_random_uuid(); partner uuid:=gen_random_uuid(); other_partner uuid:=gen_random_uuid(); car uuid:=gen_random_uuid(); foreign_car uuid:=gen_random_uuid(); app uuid; offer uuid; other_app uuid; r jsonb; payload jsonb; version text; offer_version text; request uuid:=gen_random_uuid();
 client_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex'); partner_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex'); other_hash text:=encode(digest(gen_random_uuid()::text,'sha256'),'hex');
BEGIN
 INSERT INTO public.client_profiles(id,display_name,contact) VALUES(client,'QA vehicle client','test-only');
 INSERT INTO public.partners(id,public_name,status) VALUES(partner,'QA car partner','ACTIVE'),(other_partner,'QA other partner','ACTIVE');
 INSERT INTO public.catalog_items(id,public_id,title,entity_type,owner_partner_id,availability_status,publication_status,moderation_status,client_price_thb,internal_net_thb) VALUES(car,'QA-'||car,'QA selected car','VEHICLE',partner,'AVAILABLE','PUBLISHED','APPROVED',1000,800);
 INSERT INTO public.catalog_items(id,public_id,title,entity_type,owner_partner_id,availability_status,publication_status,moderation_status,client_price_thb) VALUES(foreign_car,'QA-'||foreign_car,'QA foreign car','VEHICLE',other_partner,'AVAILABLE','PUBLISHED','APPROVED',1000);
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','CLIENT','profile_id',client,'hash',client_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','PARTNER','profile_id',partner,'hash',partner_hash));
 PERFORM pcs.portal_admin_action('issue-access',jsonb_build_object('role','PARTNER','profile_id',other_partner,'hash',other_hash));
 IF jsonb_array_length(pcs.portal_home(client_hash)->'vehicles')<>0 OR jsonb_array_length(pcs.portal_home(other_hash)->'vehicles')<>1 OR jsonb_array_length(pcs.portal_home(partner_hash)->'vehicles')<>1 OR (pcs.portal_home(partner_hash)->'vehicles')::text LIKE '%internal_net%' THEN RAISE EXCEPTION 'QA vehicle catalog scope leak';END IF;
 r:=pcs.portal_action(client_hash,'request',gen_random_uuid(),'{"need":"QA car hire"}');app:=(r->>'application_id')::uuid;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 PERFORM pcs.portal_admin_action('assign-partner',jsonb_build_object('application_id',app,'expected_version',version,'partner_id',partner));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 payload:=jsonb_build_object('application_id',app,'expected_version',version,'price','1000','deposit','200','terms','QA car terms','catalog_item_id',car,'start_date','2112-01-10','end_date','2112-01-15');
 BEGIN PERFORM pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),payload||jsonb_build_object('catalog_item_id',foreign_car));RAISE EXCEPTION 'QA foreign car accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),payload||'{"start_date":"2112-02-30"}');RAISE EXCEPTION 'QA invalid date accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM pcs.portal_action(partner_hash,'submit-offer',gen_random_uuid(),payload||'{"end_date":"2112-01-10"}');RAISE EXCEPTION 'QA empty range accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 r:=pcs.portal_action(partner_hash,'submit-offer',request,payload);offer:=(r->>'offer_id')::uuid;
 IF r<>pcs.portal_action(partner_hash,'submit-offer',request,payload) THEN RAISE EXCEPTION 'QA submit receipt mismatch';END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;SELECT updated_at::text INTO offer_version FROM public.pcs_partner_offers WHERE id=offer;
 PERFORM pcs.portal_admin_action('review-offer',jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer,'offer_version',offer_version,'decision','APPROVED'));
 IF pcs.portal_home(client_hash)#>>'{offers,0,start_date}'<>'2112-01-10' THEN RAISE EXCEPTION 'QA rental dates not shown';END IF;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;
 payload:=jsonb_build_object('application_id',app,'expected_version',version,'offer_id',offer);request:=gen_random_uuid();
 INSERT INTO public.availability_periods(item_id,starts_at,ends_at,status) VALUES(car,'2112-01-11 00:00+07','2112-01-12 00:00+07','BLOCKED');
 BEGIN PERFORM pcs.portal_action(client_hash,'select-offer',request,payload);RAISE EXCEPTION 'QA vehicle selection bypassed block';EXCEPTION WHEN exclusion_violation THEN NULL;END;
 IF (SELECT status FROM public.pcs_partner_offers WHERE id=offer)<>'APPROVED' OR EXISTS(SELECT 1 FROM pcs.portal_commands WHERE request_id=request) OR (SELECT selected_partner_offer_id FROM public.applications WHERE id=app) IS NOT NULL THEN RAISE EXCEPTION 'QA failed selection partially committed';END IF;
 DELETE FROM public.availability_periods WHERE item_id=car;
 r:=pcs.portal_action(client_hash,'select-offer',request,payload);
 IF r<>pcs.portal_action(client_hash,'select-offer',request,payload) THEN RAISE EXCEPTION 'QA selection receipt mismatch';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.applications WHERE id=app AND category='booking' AND item_id=car AND reserved_vehicle_id=car AND qualification_data->>'start_date'='2112-01-10' AND qualification_data->>'end_date'='2112-01-15') THEN RAISE EXCEPTION 'QA selected offer not reserved';END IF;
 BEGIN INSERT INTO public.applications(public_id,category,item_id,operational_status,qualification_data) VALUES('QA-'||gen_random_uuid(),'booking',car,'CONFIRMED','{"start_date":"2112-01-12","end_date":"2112-01-14"}');RAISE EXCEPTION 'QA second path bypassed selected offer';EXCEPTION WHEN exclusion_violation THEN NULL;END;
 BEGIN UPDATE public.applications SET qualification_data=qualification_data||'{"end_date":"2112-01-16"}' WHERE id=app;RAISE EXCEPTION 'QA accepted dates changed';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.applications SET category='general' WHERE id=app;RAISE EXCEPTION 'QA booking category cleared';EXCEPTION WHEN check_violation THEN NULL;END;
 BEGIN UPDATE public.applications SET selected_partner_offer_id=NULL WHERE id=app;RAISE EXCEPTION 'QA selected agreement cleared';EXCEPTION WHEN check_violation THEN NULL;END;
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(partner_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 SELECT updated_at::text INTO version FROM public.applications WHERE id=app;PERFORM pcs.portal_action(client_hash,'confirm',gen_random_uuid(),jsonb_build_object('application_id',app,'expected_version',version));
 IF NOT EXISTS(SELECT 1 FROM public.applications WHERE id=app AND operational_status='CONFIRMED' AND reserved_vehicle_id=car) THEN RAISE EXCEPTION 'QA final confirmation lost reservation';END IF;
 UPDATE public.applications SET operational_status='CANCELLED_BY_CLIENT' WHERE id=app;
 INSERT INTO public.applications(id,public_id,category,item_id,operational_status,qualification_data) VALUES(gen_random_uuid(),'QA-'||gen_random_uuid(),'booking',car,'CONFIRMED','{"start_date":"2112-01-12","end_date":"2112-01-14"}');
END;
